"use strict";
// 세션 덱은 세션 목표와 요약을 갖춰야 한다(structure.js의 checkDeckShape). 한 topic만 떼어 쓰는
// 고정 입력도 덱이므로 요약이 필요하다 — 그 요약을 한 곳에 두어 검사가 바뀔 때 함께 고친다.
// 경고를 내지 않는 모양이다: 굵은 핵심어, "### 다음 세션", 강사 노트의 "모델에서 보완된 것" 줄.
// 다른 세션·topic을 가리키지 않으므로 참조 검사에도 걸리지 않는다.
const SUMMARY_TOPIC = (number) => [
  `## ${number}. 요약`, "",
  "이 세션은 문제를 이해하고 해결책의 경계를 정하는 **판단의 흐름**을 다뤘다.", "",
  "### 다음 세션", "",
  "- **다음 세션**은 요청에서 요구를 발견해 이벤트로 합의한다.", "",
  "**강사 노트**", "",
  "- 모델에서 보완된 것 — 없다.", "",
].join("\n");

module.exports = { SUMMARY_TOPIC };
